S=[(r,c) for r,row in enumerate(A) for c,v in enumerate(row) if v==9];
for anchor in [(1,6),(4,5),(6,4),(9,1)]:
    dr,dc=anchor[0]-4,anchor[1]-5
    vals=[A[r+dr][c+dc] for r,c in S]
    print(anchor, vals, 'zeros',sum(v==0 for v in vals))

h,w=len(A),len(A[0]);
valid=[]
for dr in range(h):
 for dc in range(w):
  if all(0<=r+dr<h and 0<=c+dc<w and A[r+dr][c+dc]==0 for r,c in S): valid.append((dr,dc))
print(valid, 'count',len(valid))

sr0,sc0=min(r for r,c in S), min(c for r,c in S); Sn=[(r-sr0,c-sc0) for r,c in S]; bh=max(r for r,c in Sn)+1; bw=max(c for r,c in Sn)+1
valid=[]
for ar in range(h-bh+1):
 for ac in range(w-bw+1):
  if all(A[ar+r][ac+c]==0 for r,c in Sn): valid.append((ar,ac))
print(valid, 'count',len(valid), 'template',Sn)
